import type { ReactNode, CSSProperties } from "react";

function Row({ children, gap = 0, style }: { children?: ReactNode; gap?: number; style?: CSSProperties }) {
  return <div style={{ display: "flex", alignItems: "center", gap, ...style }}>{children}</div>;
}
function Box({ children, style }: { children?: ReactNode; style?: CSSProperties }) {
  return <div style={style}>{children}</div>;
}
function Text({ children, as: As = "span", size, tone, style }: { children?: ReactNode; as?: any; size?: number; tone?: "dim"; style?: CSSProperties }) {
  return <As style={{ fontSize: size, color: tone === "dim" ? "var(--fg-dim)" : "var(--fg)", ...style }}>{children}</As>;
}

export function SettingsRow({ label = "Enable feature", hint = "A short explanation of what this does.", children = <input type="checkbox" defaultChecked /> }: { label?: string; hint?: string; children?: ReactNode }) {
  return (
    <Row gap={12} style={{ padding: "10px 0", borderBottom: "1px solid var(--border-soft)" }}>
      <Box style={{ flex: 1, minWidth: 0 }}>
        <Text as="div" size={13} style={{ fontFamily: "var(--sans)" }}>{label}</Text>
        {hint && <Text as="div" size={11} tone="dim" style={{ fontFamily: "var(--sans)", marginTop: 2 }}>{hint}</Text>}
      </Box>
      {children}
    </Row>
  );
}

